def num_comm_div(a, b):
    # Initialize the count of common divisors
    count = 0

    # Iterate from 1 to the minimum of a and b
    for i in range(1, min(a, b) + 1):
        # Check if both a and b are divisible by i
        if a % i == 0 and b % i == 0:
            count += 1

    # Return the count of common divisors
    return count

def permutation_coefficient(n, k):
    result = 1
    for i in range(k):
        result *= (n - i)
    return result

def count_element_freq(tup):
    freq_dict = {}
    for elem in tup:
        if isinstance(elem, tuple):
            for sub_elem in elem:
                freq_dict[sub_elem] = freq_dict.get(sub_elem, 0) + 1
        else:
            freq_dict[elem] = freq_dict.get(elem, 0) + 1
    return freq_dict
